import { test, expect } from '@playwright/test';

test.describe('Duplicate Record Feature', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the application
    await page.goto('http://localhost:3000');

    // Wait for the page to load
    await page.waitForLoadState('networkidle');
  });

  test('should duplicate an existing record with one click', async ({ page }) => {
    // Create a test record first
    await page.getByRole('button', { name: /create new/i }).click();
    await page.getByLabel(/record name/i).fill('Original Record');
    await page.getByLabel(/description/i).fill('This is the original record');
    await page.getByRole('button', { name: /save/i }).click();

    // Wait for the record to be created
    await page.waitForTimeout(500);

    // Find and click the duplicate button for the created record
    const recordRow = page.getByText('Original Record').first();
    await recordRow.hover();

    // Click the duplicate button
    await page.getByRole('button', { name: /duplicate/i }).first().click();

    // Verify the duplicate was created
    await expect(page.getByText('Original Record (Copy)')).toBeVisible();

    // Verify the duplicated record has the same content
    const duplicateRow = page.getByText('Original Record (Copy)').first();
    await duplicateRow.click();

    await expect(page.getByLabel(/record name/i)).toHaveValue('Original Record (Copy)');
    await expect(page.getByLabel(/description/i)).toHaveValue('This is the original record');
  });

  test('should show duplicate button on record hover', async ({ page }) => {
    // Create a test record
    await page.getByRole('button', { name: /create new/i }).click();
    await page.getByLabel(/record name/i).fill('Test Record for Hover');
    await page.getByRole('button', { name: /save/i }).click();

    // Wait for the record to be created
    await page.waitForTimeout(500);

    // Find the record row
    const recordRow = page.getByText('Test Record for Hover').first();

    // Verify duplicate button is not visible initially
    const duplicateButton = page.getByRole('button', { name: /duplicate/i }).first();
    await expect(duplicateButton).not.toBeVisible();

    // Hover over the record
    await recordRow.hover();

    // Verify duplicate button becomes visible
    await expect(duplicateButton).toBeVisible();
  });

  test('should duplicate record with all fields preserved', async ({ page }) => {
    // Create a record with multiple fields
    await page.getByRole('button', { name: /create new/i }).click();
    await page.getByLabel(/record name/i).fill('Complete Record');
    await page.getByLabel(/description/i).fill('Full description text');
    await page.getByLabel(/category/i).selectOption('Important');
    await page.getByLabel(/priority/i).selectOption('High');
    await page.getByRole('button', { name: /save/i }).click();

    // Wait for the record to be created
    await page.waitForTimeout(500);

    // Duplicate the record
    const recordRow = page.getByText('Complete Record').first();
    await recordRow.hover();
    await page.getByRole('button', { name: /duplicate/i }).first().click();

    // Wait for duplication to complete
    await page.waitForTimeout(500);

    // Open the duplicated record
    const duplicateRow = page.getByText('Complete Record (Copy)').first();
    await duplicateRow.click();

    // Verify all fields are preserved
    await expect(page.getByLabel(/record name/i)).toHaveValue('Complete Record (Copy)');
    await expect(page.getByLabel(/description/i)).toHaveValue('Full description text');
    await expect(page.getByLabel(/category/i)).toHaveValue('Important');
    await expect(page.getByLabel(/priority/i)).toHaveValue('High');
  });

  test('should handle duplicate action for multiple records independently', async ({ page }) => {
    // Create first record
    await page.getByRole('button', { name: /create new/i }).click();
    await page.getByLabel(/record name/i).fill('Record One');
    await page.getByRole('button', { name: /save/i }).click();
    await page.waitForTimeout(500);

    // Create second record
    await page.getByRole('button', { name: /create new/i }).click();
    await page.getByLabel(/record name/i).fill('Record Two');
    await page.getByRole('button', { name: /save/i }).click();
    await page.waitForTimeout(500);

    // Duplicate the first record
    const firstRecordRow = page.getByText('Record One').first();
    await firstRecordRow.hover();
    await page.getByRole('button', { name: /duplicate/i }).first().click();
    await page.waitForTimeout(500);

    // Verify first record was duplicated
    await expect(page.getByText('Record One (Copy)')).toBeVisible();

    // Verify second record still exists and wasn't affected
    await expect(page.getByText('Record Two')).toBeVisible();

    // Duplicate the second record
    const secondRecordRow = page.getByText('Record Two').first();
    await secondRecordRow.hover();
    await page.getByRole('button', { name: /duplicate/i }).first().click();
    await page.waitForTimeout(500);

    // Verify second record was duplicated
    await expect(page.getByText('Record Two (Copy)')).toBeVisible();

    // Verify all records exist
    await expect(page.getByText('Record One')).toBeVisible();
    await expect(page.getByText('Record One (Copy)')).toBeVisible();
    await expect(page.getByText('Record Two')).toBeVisible();
    await expect(page.getByText('Record Two (Copy)')).toBeVisible();
  });
});
